 837	    .filter((item) => item.listResponses?.length || (item.value !== null && (typeof item.value !== 'object' || Object.keys(item.value).length > 0)))
 838	    .filter((item) => item.fieldTemplate.key)
 839	    .map((item) => {
 840	      let resolvedValue = item.value;
 841	
 842	      if (item.fieldTemplate.options?.length) {
